// Blendy Play footer for the site. Run in the page after it loads; safe to
// run more than once.
//
// Header logo: handled separately by mkflix-logo.css (generated by
// branding/make-icons.py), which the apps apply before the page first
// paints so the old logo never flashes.
//
// Footer: the site's footer (logo, hosting disclaimer, contact email) is
// hidden and replaced with the Blendy Play mark and one line. The mark is
// the same --mkflix-logo image the header uses, so the two always match.
// The footer element itself is kept, so its bottom padding still keeps the
// page clear of the site's bottom navigation bar on narrow screens.
//
// The site's own code owns the footer and can redraw it at any time, which
// would drop our block, so a MutationObserver puts it back whenever it is
// missing.
//
// Listing labels: "Top 10 on Cinejoy today" and the hero's "#5 on Cinejoy
// today" drop "on Cinejoy" ("Top 10 today", "#5 today"). Only the text is
// changed, so the site's own rendering keeps working.
//
// This file is shared: the desktop app loads it from mk-flix-desktop/, the
// Android app from app/src/main/assets/. Keep the two copies identical.
(function () {
  if (window.__mkflixFooter) return;
  window.__mkflixFooter = true;

  var CSS = [
    '.app-shell > footer > :not(#mkflix-footer) { display: none !important; }',
    '#mkflix-footer { display: flex; flex-direction: column; align-items: center;',
    '  gap: 0.6rem; text-align: center; }',
    '#mkflix-footer .mkf-logo { width: 44px; height: 44px;',
    '  background: var(--mkflix-logo) center / contain no-repeat; }',
    '#mkflix-footer .mkf-name { color: rgba(255,255,255,0.85); font-size: 1rem;',
    '  font-weight: 700; letter-spacing: 0.02em; }'
  ].join('\n');

  function buildFooter() {
    var box = document.createElement('div');
    box.id = 'mkflix-footer';
    var logo = document.createElement('div');
    logo.className = 'mkf-logo';
    logo.setAttribute('aria-hidden', 'true');
    box.appendChild(logo);
    var name = document.createElement('div');
    name.className = 'mkf-name';
    name.textContent = 'Blendy Play: Powered by CineJoy';
    box.appendChild(name);
    return box;
  }

  function ensure() {
    if (!document.getElementById('mkflix-footer-style') && document.head) {
      var style = document.createElement('style');
      style.id = 'mkflix-footer-style';
      style.textContent = CSS;
      document.head.appendChild(style);
    }

    var footer = document.querySelector('.app-shell > footer');
    if (footer && !footer.querySelector('#mkflix-footer')) footer.appendChild(buildFooter());
  }

  var ON_SITE = /\s+on Cinejoy\b/gi;
  function relabel() {
    if (!document.body) return;
    var walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, {
      acceptNode: function (n) {
        return /on Cinejoy/i.test(n.nodeValue) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
      }
    });
    var n, found = [];
    while ((n = walker.nextNode())) found.push(n);
    for (var i = 0; i < found.length; i++) found[i].nodeValue = found[i].nodeValue.replace(ON_SITE, "");
  }

  var queued = false;
  function onChange() {
    ensure();
    if (queued) return;
    queued = true;
    requestAnimationFrame(function () { queued = false; relabel(); });
  }

  ensure();
  relabel();
  new MutationObserver(onChange).observe(document.documentElement, { childList: true, subtree: true, characterData: true });
})();
